import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        print('Not Blacklisted')
        return

    n = int(data[0])

    if n == 0:
        print('Not Blacklisted')
        return

    attendance = data[1:n+1]
    present_count = attendance.count('P')

    percentage = present_count / n

    if percentage < 0.25:
        print('Blacklisted')
    else:
        print('Not Blacklisted')

if __name__ == "__main__":
    main()
